"""Manifest regression for the release version generator; every input tree is synthetic."""

import importlib.util
import os
import pathlib
import plistlib
import re
import shutil
import tempfile
import tomllib
import unittest

HERE = pathlib.Path(__file__).resolve().parent
REPOSITORY = HERE.parent.parent
NIGHTLY = '1.2.3-nightly.20260913.9'
STABLE = '1.2.3'
CHECKSUM = '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef'

WORKSPACE = """[workspace]
members = ["apps/desktop", "crates/*"]

[workspace.package]
version = "0.1.0"
license = "MIT OR Apache-2.0"
"""
DESKTOP = '[package]\nname = "bytwina"\nversion.workspace = true\n'
MODEL = '[package]\nname = "model"\nversion.workspace = true\n'
LOCK = """# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "bytwina"
version = "0.1.0"
dependencies = [
 "model 0.1.0",
]

[[package]]
name = "model"
version = "0.1.0"

[[package]]
name = "serde"
version = "1.0.0"
source = "registry+https://github.com/rust-lang/crates.io-index"
"""
PLIST = """<?xml version="1.0" encoding="UTF-8"?>
<plist version="1.0"><dict>
<key>CFBundleName</key><string>Bytwina</string>
<key>CFBundleShortVersionString</key><string>0.1.0</string>
</dict></plist>
"""
PLIST_WITH_BUILD = """<?xml version="1.0" encoding="UTF-8"?>
<plist version="1.0"><dict>
<key>CFBundleShortVersionString</key><string>0.1.0</string>
<key>CFBundleVersion</key><string>0.1.0</string>
</dict></plist>
"""
NSI = """Unicode True

!ifndef VERSION
  !define VERSION "0.1.0"
!endif

Name "${PRODUCT_NAME} ${VERSION}"
"""
CASK = f"""cask "bytwina" do
  version "0.1.0"
  sha256 "{CHECKSUM}"

  url "https://github.com/BytwLumina/Bytwina/releases/download/v#{{version}}/bytwina-v#{{version}}-macOS-ARM64.zip"
end
"""
# Pinned by the shipped recipe: pkgver names the asset, so pkgver and the URL move together.
PINNED_TAG = 'v1.0.0-nightly.20261001.53'
PINNED_PKGVER = '1.0.0pre.nightly.20261001.53'
PINNED_URL = (
    'https://github.com/BytwLumina/Bytwina/releases/download/'
    f'{PINNED_TAG}/bytwina-{PINNED_TAG}-Linux-arch-bytwina-{PINNED_PKGVER}-1-x86_64.pkg.tar.zst'
)


def recipe(pkgver=PINNED_PKGVER, url=PINNED_URL, checksum=CHECKSUM):
    return f"""pkgname=bytwina-bin
pkgver={pkgver}
pkgrel=1
provides=("bytwina=$pkgver")
source_x86_64=('{url}')
sha256sums_x86_64=('{checksum}')

package() {{
  install -d "$pkgdir/usr/bin"
}}
"""


class Fixture:
    """Reduced release tree holding exactly the manifests the generator owns."""

    def __init__(self, arch=None, plist=PLIST):
        self.arch = arch
        self.plist = plist

    def __enter__(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.root = pathlib.Path(self.temporary.name)
        files = {
            'Cargo.toml': WORKSPACE,
            'apps/desktop/Cargo.toml': DESKTOP,
            'crates/model/Cargo.toml': MODEL,
            'Cargo.lock': LOCK,
            'fuzz/Cargo.lock': LOCK,
            'packaging/macos/Info.plist': self.plist,
            'packaging/windows/installer.nsi': NSI,
            'Casks/bytwina.rb': CASK,
        }
        if self.arch is not None:
            files['packaging/aur/PKGBUILD'] = self.arch
        for name, content in files.items():
            write(self.root / name, content)
        self.previous = pathlib.Path.cwd()
        os.chdir(self.root)
        return self

    def __exit__(self, *error):
        os.chdir(self.previous)
        self.temporary.cleanup()
        return False

    def text(self, name):
        return (self.root / name).read_text()


def write(path, content):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)


def local_versions(lock_text):
    return {
        package['name']: package['version']
        for package in tomllib.loads(lock_text)['package']
        if 'source' not in package
    }


spec = importlib.util.spec_from_file_location('bytwina_version', HERE / 'version.py')
generate = importlib.util.module_from_spec(spec)
spec.loader.exec_module(generate)


class ArchPkgver(unittest.TestCase):
    def test_matches_the_naming_used_by_the_arch_packager(self):
        self.assertEqual(generate.arch_pkgver(NIGHTLY), '1.2.3pre.nightly.20260913.9')
        self.assertEqual(generate.arch_pkgver(STABLE), '1.2.3')

    def test_nightlies_sort_below_their_stable_base(self):
        self.assertLess(generate.release_order(NIGHTLY), generate.release_order(STABLE))
        self.assertLess(generate.release_order('1.2.3-nightly.20260913.9'),
                        generate.release_order('1.2.3-nightly.20260914.1'))
        with self.assertRaises(ValueError):
            generate.release_order('1.2.3-rc.1')


class ManifestRewrites(unittest.TestCase):
    def test_every_owned_manifest_is_rewritten(self):
        with Fixture(arch=recipe()) as tree:
            generate.update(NIGHTLY)
            self.assertEqual(
                tomllib.loads(tree.text('Cargo.toml'))['workspace']['package']['version'], NIGHTLY)
            for lock in ['Cargo.lock', 'fuzz/Cargo.lock']:
                self.assertEqual(local_versions(tree.text(lock)), {'bytwina': NIGHTLY, 'model': NIGHTLY})
                self.assertNotIn('"model 0.1.0"', tree.text(lock))
                self.assertIn(f'"model {NIGHTLY}"', tree.text(lock))
            self.assertEqual(plistlib.loads((tree.root / 'packaging/macos/Info.plist').read_bytes())
                             ['CFBundleShortVersionString'], '1.2.3')
            self.assertIn(f'!define VERSION "{NIGHTLY}"', tree.text('packaging/windows/installer.nsi'))
            self.assertIn(f'version "{NIGHTLY}"', tree.text('Casks/bytwina.rb'))
            self.assertIn(f'sha256 "{CHECKSUM}"', tree.text('Casks/bytwina.rb'))

    def test_stable_release_drops_the_prerelease_suffix_everywhere(self):
        with Fixture(arch=recipe()) as tree:
            generate.update(NIGHTLY)
            generate.update(STABLE)
            self.assertIn(f'!define VERSION "{STABLE}"', tree.text('packaging/windows/installer.nsi'))
            self.assertIn(f'version "{STABLE}"', tree.text('Casks/bytwina.rb'))
            self.assertEqual(plistlib.loads((tree.root / 'packaging/macos/Info.plist').read_bytes())
                             ['CFBundleShortVersionString'], '1.2.3')

    def test_bundle_version_is_updated_when_a_plist_carries_it(self):
        with Fixture(arch=recipe(), plist=PLIST_WITH_BUILD) as tree:
            generate.update(NIGHTLY)
            values = plistlib.loads((tree.root / 'packaging/macos/Info.plist').read_bytes())
            self.assertEqual(values['CFBundleShortVersionString'], '1.2.3')
            self.assertEqual(values['CFBundleVersion'], '1.2.3')

    def test_running_twice_changes_nothing(self):
        with Fixture(arch=recipe()) as tree:
            generate.update(NIGHTLY)
            first = {
                name: (tree.root / name).read_bytes()
                for name in ['Cargo.toml', 'Cargo.lock', 'fuzz/Cargo.lock',
                             'packaging/macos/Info.plist', 'packaging/windows/installer.nsi',
                             'Casks/bytwina.rb', 'packaging/aur/PKGBUILD']
            }
            generate.update(NIGHTLY)
            for name, content in first.items():
                self.assertEqual((tree.root / name).read_bytes(), content, name)

    def test_missing_manifest_literals_are_refused(self):
        for name, label in [('packaging/windows/installer.nsi', 'Windows installer'),
                            ('Casks/bytwina.rb', 'Homebrew cask'),
                            ('packaging/macos/Info.plist', 'Mac bundle')]:
            with Fixture(arch=recipe()) as tree:
                write(tree.root / name, re.sub(r'(VERSION "|version "|<string>)0\.1\.0', r'\1', tree.text(name)))
                with self.assertRaisesRegex(ValueError, f'Cannot locate {label}'):
                    generate.update(NIGHTLY)

    def test_absent_manifests_are_skipped_not_fatal(self):
        with Fixture(arch=recipe()) as tree:
            for name in ['packaging/windows/installer.nsi', 'Casks/bytwina.rb']:
                (tree.root / name).unlink()
            generate.update(NIGHTLY)
            self.assertEqual(
                tomllib.loads(tree.text('Cargo.toml'))['workspace']['package']['version'], NIGHTLY)


class MalformedVersions(unittest.TestCase):
    def test_rejects_and_writes_nothing(self):
        for version in ['', '1.2', '1.2.3.4', '01.2.3', 'v1.2.3', '1.2.3-rc.1',
                        '1.2.3-nightly', '1.2.3-nightly.20260913', '1.2.3-nightly.a.9']:
            with Fixture(arch=recipe()) as tree:
                before = {
                    name: (tree.root / name).read_bytes()
                    for name in ['Cargo.toml', 'Cargo.lock', 'packaging/windows/installer.nsi',
                                 'Casks/bytwina.rb', 'packaging/macos/Info.plist']
                }
                with self.assertRaisesRegex(ValueError, 'stable or nightly'):
                    generate.update(version)
                for name, content in before.items():
                    self.assertEqual((tree.root / name).read_bytes(), content, name)


class ArchRecipe(unittest.TestCase):
    """pkgver names a published asset plus its checksum, so it is checked rather than rewritten."""

    def test_lagging_but_internally_consistent_pin_is_accepted_untouched(self):
        original = recipe()
        with Fixture(arch=original) as tree:
            generate.update(NIGHTLY)
            self.assertEqual(tree.text('packaging/aur/PKGBUILD'), original)

    def test_pkgver_moved_without_its_asset_or_checksum(self):
        with Fixture(arch=recipe(pkgver=generate.arch_pkgver(NIGHTLY))) as tree:
            with self.assertRaisesRegex(ValueError, 'declares pkgver'):
                generate.update(NIGHTLY)

    def test_asset_must_be_named_from_the_release_tag_it_downloads(self):
        broken = PINNED_URL.replace(f'bytwina-{PINNED_TAG}', 'bytwina-v9.9.9-nightly.1.1')
        with Fixture(arch=recipe(url=broken)) as tree:
            with self.assertRaisesRegex(ValueError, 'named from its release tag'):
                generate.update(NIGHTLY)

    def test_tag_and_pkgver_must_render_to_each_other(self):
        # Both pkgver copies move together, so only the release tag disagrees with them.
        drifted = '1.0.0pre.nightly.20261001.99'
        url = PINNED_URL.replace(PINNED_PKGVER, drifted)
        with Fixture(arch=recipe(pkgver=drifted, url=url)) as tree:
            with self.assertRaisesRegex(ValueError, 'under pkgver'):
                generate.update(NIGHTLY)

    def test_recipe_cannot_pin_a_release_that_has_not_been_cut(self):
        future_tag = 'v1.2.4-nightly.20261001.53'
        future_pkgver = '1.2.4pre.nightly.20261001.53'
        url = (f'https://github.com/BytwLumina/Bytwina/releases/download/{future_tag}/bytwina-'
               f'{future_tag}-Linux-arch-bytwina-{future_pkgver}-1-x86_64.pkg.tar.zst')
        with Fixture(arch=recipe(pkgver=future_pkgver, url=url)) as tree:
            with self.assertRaisesRegex(ValueError, 'newer than'):
                generate.update(NIGHTLY)

    def test_checksum_is_mandatory(self):
        source = recipe().replace(f"'{CHECKSUM}'", "'TODO'")
        with Fixture(arch=source) as tree:
            with self.assertRaisesRegex(ValueError, 'Cannot locate Arch checksum'):
                generate.update(NIGHTLY)

    @unittest.skipUnless((REPOSITORY / 'packaging/aur/PKGBUILD').is_file(),
                         'the shipped recipe is not in this tree')
    def test_shipped_recipe_passes_for_a_later_release(self):
        shipped = (REPOSITORY / 'packaging/aur/PKGBUILD').read_text()
        with Fixture(arch=shipped) as tree:
            generate.update(NIGHTLY)
            self.assertEqual(tree.text('packaging/aur/PKGBUILD'), shipped)


class CommandLine(unittest.TestCase):
    def test_runs_from_the_repository_root_of_the_current_directory(self):
        with Fixture(arch=recipe()) as tree:
            import subprocess
            subprocess.run([os.sys.executable, str(HERE / 'version.py'), NIGHTLY], check=True)
            self.assertIn(f'!define VERSION "{NIGHTLY}"', tree.text('packaging/windows/installer.nsi'))

    def test_malformed_argument_exits_nonzero(self):
        import subprocess
        with Fixture(arch=recipe()):
            result = subprocess.run([os.sys.executable, str(HERE / 'version.py'), '1.2'],
                                    capture_output=True, text=True)
            self.assertNotEqual(result.returncode, 0)
            self.assertIn('stable or nightly', result.stderr)


if __name__ == '__main__':
    unittest.main()
